use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Author-requested extension: record the input received under `last-input`.
        // This does not affect the node's output.
        let recorded = subscriptions.urls.join("\n");
        state_rw::put("last-input", &recorded);

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            // A host outside the allowlist traps at the boundary; transport
            // failures come back as values so one dead feed does not fail the run.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

